    if (limit < 1 || limit > (int64_t)sizeof(buffer)) { result.kind = 1; return result; }
    file = (FILE *)h->pointer;
    count = fread(buffer, 1, (size_t)limit, file);
    if (ferror(file)) { result.value = v_text("cannot read stream", 18); return result; }
    result.kind = 0;
    result.value = v_text("", 0);
